// ratelimit_test.go
package ratelimit

import (
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (f *fakeClock) Now() time.Time { return f.t }

func (f *fakeClock) Advance(d time.Duration) { f.t = f.t.Add(d) }

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   int
		wantErr bool
	}{
		{"valid", 10, 5, false},
		{"zero rate", 0, 5, true},
		{"negative rate", -1, 5, true},
		{"zero burst", 10, 0, true},
		{"negative burst", 10, -3, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, nil)
			if (err != nil) != tc.wantErr {
				t.Fatalf("New(%v, %v) err = %v, wantErr %v", tc.rate, tc.burst, err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name  string
		rate  float64
		burst int
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name:  "burst up to capacity then denied",
			rate:  1, burst: 3,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 1, false},
			},
		},
		{
			name:  "refill over time",
			rate:  2, burst: 2, // 1 token per 500ms
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
			name:  "tokens capped at burst",
			rate:  10, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{time.Hour, 2, true}, // refilled far more than burst, capped
				{0, 1, false},
			},
		},
		{
			name:  "partial refill denies large request",
			rate:  1, burst: 5,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, true},
				{500 * time.Millisecond, 1, false}, // only 0.5 tokens
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name:  "negative request denied",
			rate:  1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := New(tc.rate, tc.burst, fc)
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			for i, s := range tc.steps {
				fc.Advance(s.advance)
				if got := l.AllowN(fc.Now(), s.n); got != s.want {
					t.Errorf("step %d: AllowN(%v) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllow(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, err := New(1, 1, fc)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !l.Allow(fc.Now()) {
		t.Fatal("first Allow = false, want true")
	}
	if l.Allow(fc.Now()) {
		t.Fatal("second Allow = true, want false")
	}
	fc.Advance(time.Second)
	if !l.Allow(fc.Now()) {
		t.Fatal("Allow after refill = false, want true")
	}
}

func TestConcurrentUse(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l, err := New(1000, 100, fc)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var wg sync.WaitGroup
	allowed := make(chan struct{}, 1000)
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow(fc.Now()) {
				allowed <- struct{}{}
			}
		}()
	}
	wg.Wait()
	close(allowed)
	if len(allowed) != 100 {
		t.Errorf("got %d allowed, want 100", len(allowed))
	}
}
